class Solution:
    def minMaxSums(self, nums: List[int], k: int) -> int:
        MOD = 10**9 + 7
        n = len(nums)
        ans = 0
        for mask in range(1, 1 << n):
            if mask.bit_count() > k:
                continue
            vals = [nums[i] for i in range(n) if mask >> i & 1]
            ans = (ans + min(vals) + max(vals)) % MOD
        return ans

