        const long long MOD = 1e9 + 7;
        int n = nums.size();
        long long ans = 0;
        for (int mask = 1; mask < (1 << n); ++mask) {
            if (__builtin_popcount(mask) > k) continue;
            int mn = INT_MAX, mx = INT_MIN;
            for (int i = 0; i < n; ++i)
                if (mask >> i & 1) { mn = min(mn, nums[i]); mx = max(mx, nums[i]); }
            ans = (ans + mn + mx) % MOD;
        }
        return ans;
    }
};

