class Solution {
public:
    int minMaxSums(vector<int>& nums, int k) {
        const long long MOD = 1e9 + 7;
        sort(nums.begin(), nums.end());
        int n = nums.size();
        vector<long long> f(n + 1, 1), inv(n + 1, 1);
        for (int i = 1; i <= n; i++) f[i] = f[i - 1] * i % MOD;
        inv[n] = 1;
        long long b = 1, e = MOD - 2, base = f[n];
        while (e) { if (e & 1) b = b * base % MOD; base = base * base % MOD; e >>= 1; }
        inv[n] = b;
        for (int i = n; i >= 1; i--) inv[i - 1] = inv[i] * i % MOD;
        auto C = [&](int a, int c) -> long long {
            if (c < 0 || c > a) return 0;
            return f[a] * inv[c] % MOD * inv[a - c] % MOD;
        };
        long long ans = 0;
        for (int i = 0; i < n; i++)
            for (int j = 0; j < k; j++)
                ans = (ans + nums[i] % MOD * ((C(n - 1 - i, j) + C(i, j)) % MOD)) % MOD;
        return ans;
    }
};

