class Solution {
    public int minMaxSums(int[] nums, int k) {
        final long MOD = 1_000_000_007L;
        Arrays.sort(nums);
        int n = nums.length;
        long[] f = new long[n + 1], inv = new long[n + 1];
        f[0] = 1;
        for (int i = 1; i <= n; i++) f[i] = f[i - 1] * i % MOD;
        inv[n] = pow(f[n], MOD - 2, MOD);
        for (int i = n; i >= 1; i--) inv[i - 1] = inv[i] * i % MOD;
        long ans = 0;
        for (int i = 0; i < n; i++)
            for (int j = 0; j < k; j++)
                ans = (ans + nums[i] % MOD * ((C(n - 1 - i, j, f, inv, MOD) + C(i, j, f, inv, MOD)) % MOD)) % MOD;
        return (int) ans;
    }
    private long C(int a, int b, long[] f, long[] inv, long MOD) {
        if (b < 0 || b > a) return 0;
        return f[a] * inv[b] % MOD * inv[a - b] % MOD;
    }
    private long pow(long b, long e, long m) {
        long r = 1; b %= m;
        while (e > 0) { if ((e & 1) == 1) r = r * b % m; b = b * b % m; e >>= 1; }
        return r;
    }
}

